"""Real entry-point export used by the Extension compatibility tests."""

from __future__ import annotations

import os

from core.extension_contracts import (
    CommandContribution,
    ExtensionContributions,
    ExtensionManifest,
    PhaseContribution,
    PromptContribution,
)
from core.tool_registry import ToolSpec

from pawnlogic_compat_fixture import record_event

EXTENSION_NAME = "compat-fixture"
EXTENSION_VERSION = "1.0.0"
TOOL_NAME = "compat_fixture_tool"
COMMAND_NAME = "/compat-fixture"
PHASE_NAME = "COMPAT_FIXTURE"
PROMPT_NAME = "compat-fixture-prompt"


def _tool_handler(arguments: dict) -> dict:
    return {"fixture": "ok", "arguments": arguments}


def _command_handler(_context: object) -> str:
    return "compat fixture command"


def _contributions() -> ExtensionContributions:
    tool = ToolSpec(
        name=TOOL_NAME,
        handler=_tool_handler,
        schema={
            "type": "function",
            "function": {
                "name": TOOL_NAME,
                "description": "Return local Extension compatibility fixture data.",
                "parameters": {"type": "object", "additionalProperties": False},
            },
        },
        phases=frozenset({PHASE_NAME}),
    )
    return ExtensionContributions(
        tools=(tool,),
        commands=(CommandContribution(COMMAND_NAME, _command_handler),),
        phases=(PhaseContribution(PHASE_NAME, {"fixture": True}),),
        prompts=(PromptContribution(PROMPT_NAME, "Use the compatibility fixture.", 10),),
    )


class CompatibilityExtension:
    """Small lifecycle implementation with deterministic failure modes."""

    def __init__(self) -> None:
        mode = os.environ.get("PAWNLOGIC_EXTENSION_FIXTURE_MODE", "ok")
        core_version_spec = ">=999" if mode == "incompatible" else ">=0.2,<1"
        self.mode = mode
        self.manifest = ExtensionManifest(
            name=EXTENSION_NAME,
            version=EXTENSION_VERSION,
            core_version_spec=core_version_spec,
            api_version=1,
            description="Installed-layout Extension compatibility fixture.",
            capabilities=frozenset({"tools.read_only"}),
            config_schema={"type": "object", "additionalProperties": False},
        )

    def start(self, context: object) -> ExtensionContributions:
        record_event("start")
        contributions = _contributions()
        if self.mode == "start-fails":
            context.tools.register_many(contributions.tools)
            context.commands.register_many(contributions.commands)
            context.phases.register_many(contributions.phases)
            context.prompts.register_many(contributions.prompts)
            raise RuntimeError("compatibility fixture start failed")
        return contributions

    def stop(self) -> None:
        record_event("stop")


extension = CompatibilityExtension()
